const fs = await import('node:fs');
const path = await import('node:path');
const pdfjs = await import('pdfjs-dist');
const workerPath = path.join(process.cwd(), 'node_modules', 'pdfjs-dist', 'build', 'pdf.worker.min.mjs');
pdfjs.GlobalWorkerOptions.workerSrc = workerPath;
const data = fs.readFileSync(globalThis.pdf_path);
globalThis.pdfData = new Uint8Array(data);

const loadingTask = pdfjs.getDocument({ data: globalThis.pdfData });
const pdf = await loadingTask.promise;
const allText = [];
for (let i = 1; i <= pdf.numPages; i++) {
  const page = await pdf.getPage(i);
  const textContent = await page.getTextContent();
  const pageText = textContent.items.map(item => item.str).join(' ');
  allText.push(pageText);
}
globalThis.allText = allText;

const lines = globalThis.allText.join('\n').split('\n');
const headings = [];
for (const line of lines) {
  const trimmed = line.trim();
  if (trimmed.length > 0 && trimmed.length < 100) {
    if (/^[A-Z][a-z]+ [A-Z][a-z]+/.test(trimmed) || /^[A-Z]{2,}$/.test(trimmed)) {
      headings.push(trimmed);
    }
  }
}
globalThis.headings = headings;
